---
description: A synthesized program.
returns: Num
uses:
  mentions_side_effects: ./mentions_side_effects
  kind_of_study: ./kind_of_study
  in_adults: ./in_adults
  select_by_flags: ./select_by_flags
  group_count: ./group_count
---
function abstract_triage(abstracts) -> { by_topic: Dict<Num>, by_designs: Dict<Num>, share: Num }

  let side_effects = for x in abstracts do mentions_side_effects(x)
  let designs = for x in abstracts do kind_of_study(x)
  let adults_only = for x in abstracts do in_adults(x)
  subset = select_by_flags(abstracts, adults_only)
  if subset is empty:
      by_topic = {}
  else:
      study_kinds = [kind_of_study(x) for x in subset]
      by_topic = group_count(study_kinds)
  by_designs = group_count(designs)
  share = share of true in side_effects, rounded to 2 decimals     # exact
  return { by_topic, by_designs, share }

judge_move.code:
const draw = c => [0, 3, 6].map(i => c.slice(i, i + 3).map(v => v === "empty" ? "." : v).join(" ")).join("\n")
const t = args.target
if (!Number.isInteger(t) || t < 1 || t > 9) return { legal: false, reason: `there is no cell ${t}`, wins: false, board: draw(args.cells) }
if (args.cells[t - 1] !== "empty") return { legal: false, reason: `cell ${t} is already taken by ${args.cells[t - 1]}`, wins: false, board: draw(args.cells) }
const next = args.cells.slice(); next[t - 1] = args.player
const lines = [[0,1,2],[3,4,5],[6,7,8],[0,3,6],[1,4,7],[2,5,8],[0,4,8],[2,4,6]]
const wins = lines.some(l => l.every(i => next[i] === args.player))
return { legal: true, reason: wins ? "legal, and it wins the game" : "legal", wins, board: draw(next) }

handle_mail.instructions:
function handle_mail(email) -> Decision

  landlord = from_landlord(email)
  if not landlord:
      return { action: "archive", date: "" }
  date = find_date(email)                               # "" when the email names no date
  if date is "":
      return { action: "reply_later", date: "" }
  add_to_calendar(date, email)                          # effect
  return { action: "calendar", date }

$lambda.instructions:
function moderate(post, policy) -> Decision

  rules = split_rules(policy)                                   # exact: one rule per line
  flags = for each r in rules: violates(r, post)
  hits  = select_by_flags(rules, flags)
  if hits is empty:
      return { action: "allow", rules: [], note: "No rule applies." }

  severities = for each r in hits: severity_of(r, post)
  if no severity is "high":                                     # exact: use code
      return { action: "warn", rules: hits, note: "Minor: the author is reminded of the rules." }

  # Removal is drastic: get a second opinion from a stricter reader before acting.
  strict = a copy of violates, with "When in doubt, answer true." replaced by
           "Answer true only if the violation is unmistakable. When in doubt, answer false."
  confirmed_flags = for each r in hits: strict(r, post)
  confirmed = select_by_flags(hits, confirmed_flags)
  if confirmed is empty:
      return { action: "escalate", rules: hits, note: "A serious rule may apply, but it is not clear-cut. A human should look." }
  return { action: "remove", rules: confirmed, note: "A serious violation, confirmed on a strict reading." }

