if (price === undefined) return out.concat([{ code: "chat", good: "", qty: 0, price: 0 }])
out.push({ code: "quote", good: i.good, qty: 0, price })
const qty = Math.max(1, Math.min(i.qty || 1, have))
if (have > 0 && (i.kind === "buy" || i.kind === "haggle")) {
  out.push({ code: "sell_list_price", good: i.good, qty, price })
  const floor = Math.ceil(price * 0.8)                       // never below 80% of the list price
  if (i.kind === "haggle" && i.offer >= floor) out.push({ code: "sell_at_offer", good: i.good, qty, price: Math.min(i.offer, price) })
  if (i.kind === "haggle" && i.offer < floor) out.push({ code: "counter_offer", good: i.good, qty, price: floor })
}
if (have === 0) out.push({ code: "out_of_stock", good: i.good, qty: 0, price })
return out

apply_submission.code:
if (!args.review.accept || !args.review.message.trim()) return args.acc
const entry = { author: args.review.author.trim().slice(0, 60) || "anonymous", message: args.review.message.trim().slice(0, 500) }
return { ...args.acc, entries: args.acc.entries.concat([entry]).slice(-50) }

error_response.code:
const notAllowed = args.route.kind === "method_not_allowed"
return { status: notAllowed ? 405 : 404, headers: Object.assign({ "Content-Type": "text/html; charset=utf-8" }, notAllowed ? { "Allow": args.route.purpose } : {}),
         body: `<!doctype html><title>${notAllowed ? 405 : 404}</title><h1>${notAllowed ? "Method not allowed" : "Not found"}</h1><p><a href="/">home</a></p>` }

match_route.code:
const hit = args.routes.find(r => r.path === args.req.path)
if (!hit) return { kind: "not_found", name: args.req.path, purpose: "", asset: "" }
if (!hit.methods.includes(args.req.method)) return { kind: "method_not_allowed", name: hit.path, purpose: hit.methods.join(", "), asset: "" }
return { kind: hit.kind, name: hit.path, purpose: hit.purpose, asset: hit.asset || "" }

parse_request.code:
const dec = s => { try { return decodeURIComponent(s.replace(/\+/g, " ")) } catch (e) { return s } }
const pairs = s => Object.fromEntries((s || "").split("&").filter(Boolean).map(p => { const i = p.indexOf("="); return i < 0 ? [dec(p), ""] : [dec(p.slice(0, i)), dec(p.slice(i + 1))] }))
const [path, qs] = args.item.path.split("?")
const cookie = Object.entries(args.item.headers).find(([k]) => lower(k) === "cookie")
const sid = cookie ? (cookie[1].match(/(?:^|;\s*)sid=([A-Za-z0-9_-]+)/) || [])[1] : ""
return { id: args.item.id, method: args.item.method.toUpperCase(), path: path.replace(/\/+$/, "") || "/", query: pairs(qs),
         form: args.item.method.toUpperCase() === "POST" ? pairs(args.item.body) : {}, session_id: sid || "" }

session_for.code:
const old = args.acc.sessions[args.req.session_id]
if (old) return { ...old, visits: old.visits + 1 }
return { id: "s" + (Object.keys(args.acc.sessions).length + 1) + "x" + args.req.id.replace(/[^A-Za-z0-9]/g, ""), visits: 1, name: "" }

static_response.code:
const body = args.acc.assets[args.route.asset]
if (body === undefined) return { status: 404, headers: { "Content-Type": "text/plain; charset=utf-8" }, body: "Not found" }
const type = args.route.asset.endsWith(".css") ? "text/css" : args.route.asset.endsWith(".txt") ? "text/plain" : "text/html"
return { status: 200, headers: { "Content-Type": type + "; charset=utf-8", "Cache-Control": "max-age=3600" }, body }

wrap_page.code:
const esc = s => s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
const safe = args.content.replace(/<\s*script[\s\S]*?<\s*\/\s*script\s*>/gi, "").replace(/\son\w+\s*=\s*("[^"]*"|'[^']*'|[^\s>]+)/gi, "")
const nav = args.acc.routes.filter(r => r.kind === "page").map(r => `<a href="${r.path}">${esc(r.path === "/" ? "home" : r.path.slice(1))}</a>`).join(" · ")
const html = `<!doctype html><html><head><meta charset="utf-8"><title>${esc(args.acc.name)}</title><link rel="stylesheet" href="/style.css"></head>` +
             `<body><header><h1>${esc(args.acc.name)}</h1><nav>${nav}</nav></header><main>${safe}</main></body></html>`
return { status: 200, headers: { "Content-Type": "text/html; charset=utf-8", "Set-Cookie": `sid=${args.session.id}; Path=/; HttpOnly; SameSite=Lax` }, body: html }
